import * as THREE from 'three';
import type { Handedness, XRInput } from './XRInput';
import { FreeLocomotion, type Locomotion } from './Locomotion';
import { STANDING_EYE, eyeHeights, playerPosture, seatedLift, type Posture } from './posture';
import {
  forwardOfYaw,
  newWalkFrame,
  turnWalkFrame,
  walkYaw,
  yawOfForward,
  type WalkFacing,
} from './walkFrame';

const UP = new THREE.Vector3(0, 1, 0);
const _head = new THREE.Vector3();
const _quat = new THREE.Quaternion();
const _euler = new THREE.Euler();
const _mat = new THREE.Matrix4();
const _scale = new THREE.Vector3();
const _forward = new THREE.Vector3();
const _strafe = new THREE.Vector3();
const _delta = new THREE.Vector3();

/**
 * The player's "room": the camera and all controllers live inside this group,
 * so moving/rotating the rig moves the player without touching the headset pose.
 */
export class PlayerRig extends THREE.Group {
  /** Metres per second for stick locomotion. */
  moveSpeed = 2.6;
  /** How much faster sprinting is than walking. */
  sprintFactor = 1.9;
  /**
   * Wie viel vom Sprint gerade wirklich übrig ist, 0…1 — die **Puste**.
   *
   * Der Sprint war bis eben unbegrenzt, und in einer Welt mit einem Verfolger
   * ist das keine Fähigkeit, sondern das Ende jeder Verfolgung: Wer geradeaus
   * läuft, kommt immer davon. Wie viel Puste jemand hat und wie schnell sie
   * zurückkommt, entscheidet die Welt und nicht das Gestell — hier steht nur
   * die eine Zahl, mit der sie es sagt (`haunting/mission.ts`,
   * `stepStamina`). 1 heißt: unbegrenzt, wie in jeder anderen Welt.
   */
  sprintScale = 1;
  /**
   * **Die Tempo-Regel einer Welt** — Gehen und Sprint in m/s, gefragt je Bild,
   * für Brille, Tastatur und Bildschirmstock gleichermaßen. `null` heißt: die
   * Voreinstellung des Gestells (`moveSpeed`, `sprintFactor`) in der Brille
   * und die der Tastatur (`FlatControls.speed`) am Schirm. Haunting hängt hier
   * `mission.ts` ein, samt Puste — vorher lief der Tastaturspieler dort mit
   * 3,2 m/s statt 2,6 und ohne jede Puste, und die Ungleichung „Monster
   * schneller als ein gehender Spieler" galt nur in der Brille.
   */
  pace: ((sprint: boolean) => number) | null = null;
  /** Ob Tastatur oder Bildschirmstock in diesem Bild sprinten wollten (`setIntent`). */
  private intentSprint = false;
  /** Was `sprinting` und `wishing` für dieses Bild sagen — festgehalten in `update`. */
  private sprintedNow = false;
  private wished = false;
  /**
   * Sprint is held down by default (left stick pressed in). Switched over in
   * the settings it toggles instead — for anybody who does not want to keep a
   * stick pressed while crossing the whole map.
   */
  sprintToggle = false;
  /** Crouch toggles by default; held works the same way as sprint. */
  crouchToggle = true;
  /** How far the view drops while crouching. */
  crouchDepth = 0.55;
  /** Metres per second the view sinks and rises again. */
  crouchSpeed = 1.8;
  /** Radians per snap turn. */
  snapAngle = THREE.MathUtils.degToRad(30);
  /** Worlds may opt into continuous turning; existing worlds keep snap turns. */
  turnMode: 'snap' | 'smooth' = 'snap';
  /** Radians per second at full right-stick deflection in smooth mode. */
  smoothTurnSpeed = THREE.MathUtils.degToRad(60);
  /**
   * Woran sich die Laufrichtung hält (`walkFrame.ts`).
   *
   * Voreingestellt ist `'start'`: Wer losläuft, merkt sich damit die Richtung
   * und darf den Kopf danach frei bewegen. `'head'` ist das alte Verhalten und
   * steht unter *Menü → Bewegung*.
   */
  walkFacing: WalkFacing = 'start';
  /** Eye height used while not in VR — the player's own, if they measured it. */
  flatEyeHeight = eyeHeights().stand / 100 || STANDING_EYE;
  /**
   * Whether the player is sitting on a chair or standing on their feet.
   *
   * The headset only knows how far the head is above the floor of the room, so
   * a seated player is simply a short one as far as every world is concerned —
   * counters get taller, karts get deeper and the horizon drops. Saying "I am
   * sitting" lifts the view back to standing height without moving the feet,
   * so the world stays the size it was built at. Set from the start page and
   * from *Menü → Bewegung → Haltung*.
   */
  posture: Posture = playerPosture();
  /**
   * Wie weit ein sitzender Spieler angehoben wird, in Metern — die Differenz
   * zwischen seiner eigenen Steh- und Sitz-Augenhöhe (`posture.ts`).
   *
   * Das war früher `STANDING_EYE` minus der *gerade gemessenen* Kopfhöhe, und
   * das hatte zwei Fehler auf einmal: es unterstellte allen dieselbe Größe,
   * und es rechnete jede Bewegung im Sessel mit. Wer sich vorbeugte, hob damit
   * die ganze Welt an. Jetzt sind es zwei Zahlen, die der Spieler einmal misst,
   * und dazwischen bewegt sich nichts mehr.
   */
  seatHeight = seatedLift();

  locomotion: Locomotion = new FreeLocomotion();
  /**
   * Freezes locomotion and stick input. Set while a spectator view drives the
   * rig — the player is a camera then, not a body in the world.
   */
  paused = false;
  /**
   * The same, but asked for by the world instead of by the engine: the drone
   * takes the view away from the body, and a body that keeps walking and
   * falling while nobody is looking is a body you come back to somewhere else.
   * The engine folds this into `paused` every frame.
   */
  frozen = false;
  /**
   * Stick movement, jumping and the snap turn are switched off, but the body
   * is otherwise alive — crouching, the seated lift and the head all keep
   * working. The input world uses it: there the point is to look at what your
   * hands are doing, and a stick that walks you out of the room while you do
   * it is nothing but a distraction.
   */
  locked = false;
  /**
   * Ein Stick, der diese Frame dem Menü gehört.
   *
   * Wer aufs Panel zeigt und mit dem Stick blättert, will blättern — und nicht
   * nebenbei durch den Raum laufen oder sich wegdrehen. Das Menü sagt jede
   * Frame, welche Hand es gerade braucht (`WristMenus.scrollHand`); alles
   * andere an dieser Hand bleibt normal, es ist nur der Stick.
   */
  menuStick: Handedness | null = null;

  private readonly intent = new THREE.Vector3();
  private intentJump = false;
  /** Ob `requestUse` seit dem letzten `takeUse` gedrückt wurde. */
  private useWanted = false;
  /** Der zuletzt gesetzte Triggerwert der rechten Hand (`setTrigger`). */
  private triggerValue = 0;
  private snapArmed = true;
  /** Die Richtung, die beim Loslaufen gemerkt wurde — siehe `walkFrame.ts`. */
  private readonly walkFrame = newWalkFrame();
  /**
   * How far the view currently sits below the standing pose. The headset owns
   * the camera inside the rig, so crouching can only happen by lowering the
   * rig itself — `getFloorY()` is what keeps the feet where they were.
   */
  private crouchOffset = 0;
  private crouchWanted = false;
  private sprintWanted = false;
  /**
   * How far the view is currently lifted because the player is sitting. The
   * exact mirror image of `crouchOffset`: the rig goes up, the feet stay put.
   */
  private seatLift = 0;

  constructor(
    private readonly renderer: THREE.WebGLRenderer,
    readonly camera: THREE.PerspectiveCamera,
  ) {
    super();
    this.name = 'player-rig';
    this.add(camera);
    camera.position.set(0, this.flatEyeHeight, 0);
  }

  setLocomotion(locomotion: Locomotion): void {
    this.locomotion.dispose?.();
    this.locomotion = locomotion;
  }

  /** Movement wish for this frame, in m/s. Flat controls feed this too. */
  setIntent(velocity: THREE.Vector3, jump = false, sprint = false): void {
    this.intent.copy(velocity);
    if (jump) this.intentJump = true;
    if (sprint) this.intentSprint = true;
  }

  /** Das Tempo für einen Wunsch von Tastatur oder Bildschirmstock — die Regel der Welt, sonst `fallback`. */
  walkSpeed(sprint: boolean, fallback: number): number {
    return this.pace ? this.pace(sprint) : fallback;
  }

  requestJump(): void {
    this.intentJump = true;
  }

  /**
   * **Benutzen, einmal** — `A`, `E`, Enter, der Touch-Knopf `A`
   * (`FlatControls`). Eine Flanke und keine Taste, die liegen bleibt: Wer
   * einen Knopf drückt, drückt ihn einmal, auch wenn der Finger länger auf
   * `A` bleibt.
   *
   * Der Empfänger ist die Welt und nicht das Gestell — sie weiß, was vor der
   * Figur steht (`useForward`, Paket P2 aus
   * `docs/plan-2d-hub-interaktion.md`). Hier liegt nur der Zettel dazwischen,
   * damit die Eingabe **einen** Weg hat und keine Welt eigene Tasten abhört.
   */
  requestUse(): void {
    this.useWanted = true;
  }

  /**
   * **Wie der Knopf zum Benutzen gerade heißt** — `E` an der Tastatur, `A` am
   * Gamepad und auf dem Glas. Gesetzt von `FlatControls` (die weiß, welches
   * Gerät zuletzt sprach), gelesen vom Hinweis über der Figur
   * (`PortalWorld.showUsePrompt`). Ein Hinweis, der fest `E` zeigt, ist mit
   * einem Pad in der Hand schlicht falsch.
   */
  useLabel: 'E' | 'A' = 'E';

  /**
   * **Ob gerade etwas in Reichweite steht, das man benutzen kann.**
   *
   * Gesetzt von der Welt, jedes Bild (`PortalWorld.updateUsables` →
   * `core/usable.pickUsable`), gelesen von allem, was auf `A` liegt. Denn
   * `A` ist **ein** Knopf für zwei Dinge, und das ist Absicht: Steht ein Ding
   * vor der Figur, benutzt `A` es; steht keines da, springt es. So macht es
   * jedes Spiel mit einem Knopf, und so muss niemand wissen, welcher Knopf
   * gerade welchen Sinn hat.
   *
   * Die Welt setzt es und niemand sonst; wer keine benutzbaren Dinge hat,
   * lässt es auf `false`, und `A` springt wie eh und je.
   */
  useCandidate = false;

  /**
   * **Ob der Benutzen-Knopf gerade _liegt_** — nicht die Flanke, die Taste.
   *
   * `requestUse` ist eine Flanke, und das ist für Knöpfe, Türen und Schilder
   * genau richtig: Wer drückt, drückt einmal. Es gibt aber Dinge, die ein
   * **Halten** verlangen, und das aus gutem Grund — aus einem Kart bei Tempo
   * 60 steigt man nicht aus Versehen aus (`worlds/test/zones/kart.ts`). In der
   * Brille fragt so etwas den Controller (`primary.pressed`); am Schreibtisch
   * und am Telefon gab es gar nichts zu fragen, und **deshalb kam man aus dem
   * Kart nicht mehr heraus**, sobald keine Tastatur dabei war.
   *
   * Gesetzt von `FlatControls` jedes Bild, aus allen Gebern zusammen: `E`,
   * Enter, der Knopf `A` auf dem Glas und `A` am Pad.
   */
  useHeld = false;

  /** Den Zettel lesen und wegnehmen — je Bild höchstens einmal wahr. */
  takeUse(): boolean {
    const wanted = this.useWanted;
    this.useWanted = false;
    return wanted;
  }

  /**
   * **Der Trigger der rechten Hand**, 0…1 — vom Bildschirm aus gesetzt
   * (`B`, RT, Linksklick, Touch-`B`), damit die Pistole von oben genauso
   * feuert wie in der Brille und nicht über einen zweiten Weg.
   */
  setTrigger(value: number): void {
    this.triggerValue = Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0;
  }

  /** Was zuletzt gesetzt wurde — `0`, solange niemand drückt. */
  get trigger(): number {
    return this.triggerValue;
  }

  /** Head pose in world space. Fresh, even before the frame has been rendered. */
  getHeadMatrix(target: THREE.Matrix4): THREE.Matrix4 {
    if (this.renderer.xr.isPresenting) this.renderer.xr.updateCamera(this.camera);
    return target.copy(this.camera.matrixWorld);
  }

  /**
   * Places the head at a world pose by moving the camera inside the rig — the
   * rig itself stays where the locomotion put it. Used by the spectator camera,
   * which borrows the view without disturbing the player's position.
   */
  setHeadWorldPose(position: THREE.Vector3, quaternion: THREE.Quaternion): void {
    this.updateMatrixWorld(true);
    _mat.copy(this.matrixWorld).invert();
    this.camera.position.copy(position).applyMatrix4(_mat);
    // The rig is never scaled, so the inverse's 3x3 part is a plain rotation.
    this.camera.quaternion.setFromRotationMatrix(_mat).multiply(quaternion);
    this.camera.updateMatrixWorld(true);
  }

  /**
   * Moves the whole rig so the head ends up at a world position, leaving its
   * orientation alone. In VR the headset owns the camera pose, so this is the
   * only way to put a spectating player somewhere else.
   */
  setHeadWorldPosition(position: THREE.Vector3): void {
    this.getHeadPosition(_head);
    this.position.add(_delta.copy(position).sub(_head));
    this.updateMatrixWorld(true);
  }

  getHeadPosition(target: THREE.Vector3): THREE.Vector3 {
    this.getHeadMatrix(_mat);
    return target.setFromMatrixPosition(_mat);
  }

  /** Eye height above the floor — crouching makes the body shorter, not lower. */
  getHeadHeight(): number {
    return Math.max(0.6, this.camera.position.y - this.crouchOffset + this.seatLift);
  }

  /**
   * Where the feet are. The rig sinks while crouching, the floor does not —
   * everything that stands the player on the ground asks here, not for
   * `position.y`.
   */
  getFloorY(): number {
    return this.position.y + this.crouchOffset - this.seatLift;
  }

  /** How far the view is currently dropped below the standing pose. */
  get crouch(): number {
    return this.crouchOffset;
  }

  /**
   * Optional world-owned keyboard stance. The same offset and character
   * capsule used in VR keep the desktop player's feet on the floor too.
   * Worlds that do not call this retain their existing controls.
   */
  updateDesktopCrouch(wanted: boolean, dt: number): void {
    this.crouchWanted = wanted;
    this.updateCrouch(Math.max(0, Number.isFinite(dt) ? dt : 0));
  }

  /** True while the player is sprinting — in the headset, at the keyboard or on the screen stick. */
  get sprinting(): boolean {
    return this.sprintedNow;
  }

  /** Ob in diesem Bild überhaupt jemand laufen wollte — Stock, Tastatur oder Bildschirmstock. */
  get wishing(): boolean {
    return this.wished;
  }

  /** Stands back up, e.g. when a world is left. */
  standUp(): void {
    this.locked = false;
    this.useCandidate = false;
    this.sprintScale = 1;
    this.position.y -= this.crouchOffset - this.seatLift;
    this.crouchOffset = 0;
    this.seatLift = 0;
    this.crouchWanted = false;
    this.sprintWanted = false;
    this.updateMatrixWorld(true);
  }

  /** How far the seated lift currently raises the view, in metres. */
  get seated(): number {
    return this.seatLift;
  }

  /** Horizontal viewing direction of the head, normalised. */
  getHeadForward(target: THREE.Vector3): THREE.Vector3 {
    this.getHeadMatrix(_mat);
    target.set(-_mat.elements[8]!, 0, -_mat.elements[10]!);
    if (target.lengthSq() < 1e-6) target.set(0, 0, -1);
    return target.normalize();
  }

  /**
   * Where the head actually looks, pitch included. `getHeadForward` flattens
   * the direction because walking happens on the floor; flying does not.
   */
  getHeadLook(target: THREE.Vector3): THREE.Vector3 {
    this.getHeadMatrix(_mat);
    target.set(-_mat.elements[8]!, -_mat.elements[9]!, -_mat.elements[10]!);
    if (target.lengthSq() < 1e-6) target.set(0, 0, -1);
    return target.normalize();
  }

  /**
   * Turns the player around the head until the **head** looks along `yaw`.
   *
   * `placeAt` only turns the rig, and in VR the headset adds its own yaw on
   * top: whoever stands turned left in the play space keeps looking left
   * after the rig was pointed at a door. This measures where the head looks
   * and takes the difference out around the head, so the feet stay put.
   */
  turnHeadTo(yaw: number): void {
    this.getHeadForward(_forward);
    this.rotateAroundHead(yaw - yawOfForward(_forward.x, _forward.z));
  }

  /** Rotates the player around the head, so the world does not swing away. */
  rotateAroundHead(angle: number): void {
    this.getHeadPosition(_head);
    _quat.setFromAxisAngle(UP, angle);
    this.position.sub(_head).applyQuaternion(_quat).add(_head);
    this.quaternion.premultiply(_quat);
    this.updateMatrixWorld(true);
  }

  /**
   * Applies a world-space transform to the rig (portal traversal). Any tilt is
   * dropped so the horizon stays level.
   */
  applyWorldTransform(transform: THREE.Matrix4): void {
    this.updateMatrixWorld(true);
    _mat.multiplyMatrices(transform, this.matrixWorld);
    _mat.decompose(this.position, this.quaternion, _scale);
    _euler.setFromQuaternion(this.quaternion, 'YXZ');
    this.quaternion.setFromEuler(_euler.set(0, _euler.y, 0));
    this.scale.set(1, 1, 1);
    this.updateMatrixWorld(true);
    this.locomotion.teleport?.(this, transform);
  }

  /**
   * Places the **rig's origin** at a spawn point looking along `yaw`
   * (radians). In VR that origin is the centre of the play space, not the
   * player: whoever wants the player's feet on the point uses `placeFeetAt`.
   */
  placeAt(position: THREE.Vector3, yaw = 0): void {
    // `position` is where the feet go; a crouching player sits below that, a
    // seated one above it — exactly the two offsets `getFloorY()` takes back
    // out. The seat used to be missing here, and a sitting player was set
    // `seatLift` below every point he was moved to: knee-deep in the floor
    // after the safety locker, the round start and even the rescue button.
    this.position.copy(position);
    this.position.y += this.seatLift - this.crouchOffset;
    this.quaternion.setFromEuler(_euler.set(0, yaw, 0));
    this.updateMatrixWorld(true);
  }

  /**
   * **Die Füße des Spielers auf den Punkt — nicht der Ursprung des Rigs.**
   *
   * In der Brille steht der Kopf selten über dem Ursprung des Spielraums:
   * Wer einen Meter neben der Mitte seines Guardians steht, landete mit
   * `placeAt` einen Meter neben dem Ziel — beim Missionsstart in der Wand
   * oder in der Konsole der Einsatzzentrale, und die Physik-Kapsel, die unter
   * dem Kopf sitzt (`PhysicsLocomotion.syncCapsuleToRig`), steckte damit fest.
   * Die Rettung „Zurück auf den Boden" versetzte den Ursprung noch einmal
   * genauso — und half deshalb nicht. Hier wird der Ursprung um den
   * waagerechten Versatz des Kopfes zurückgeschoben, nach dem Drehen, weil
   * der Versatz sich mitdreht; am Bildschirm sitzt die Kamera über dem
   * Ursprung, und nichts ändert sich.
   */
  placeFeetAt(position: THREE.Vector3, yaw = 0): void {
    this.placeAt(position, yaw);
    this.getHeadPosition(_head);
    this.position.x += position.x - _head.x;
    this.position.z += position.z - _head.z;
    this.updateMatrixWorld(true);
  }

  /**
   * Reads the sticks while in VR, hands the movement wish to the locomotion and
   * resets the intent for the next frame.
   *
   * @param uiActive the pointer rests on a menu — the buttons belong to it then.
   */
  update(dt: number, input: XRInput, presenting: boolean, uiActive = false): void {
    if (this.paused) {
      this.intent.set(0, 0, 0);
      this.intentJump = false;
      this.intentSprint = false;
      this.sprintedNow = false;
      this.wished = false;
      return;
    }

    if (presenting) {
      const left = input.get('left');
      this.updateStance(dt, input);
      const stick = this.locked || this.menuStick === 'left' ? null : left?.thumbstick;
      const moving = stick ? stick.x !== 0 || stick.y !== 0 : false;
      // Der Kopf sagt, wohin es geht — aber nur beim Loslaufen, wenn der
      // Spieler es so eingestellt hat (`walkFrame.ts`). Danach steht die
      // Richtung, und der Blick ist wieder frei.
      this.getHeadForward(_forward);
      const yaw = walkYaw(
        this.walkFrame,
        this.walkFacing,
        yawOfForward(_forward.x, _forward.z),
        moving,
      );
      if (stick && moving) {
        const ahead = forwardOfYaw(yaw);
        _forward.set(ahead.x, 0, ahead.z);
        _strafe.copy(_forward).cross(UP).normalize();
        _head.set(0, 0, 0).addScaledVector(_forward, -stick.y).addScaledVector(_strafe, stick.x);
        if (_head.lengthSq() > 1) _head.normalize();
        this.intent.copy(_head.multiplyScalar(this.speedNow()));
      }
      // A also confirms menu entries, so it must not jump while pointing at one.
      //
      // **Und in der Brille benutzt derselbe Knopf**, sobald etwas in
      // Reichweite steht (`useCandidate`): Die Hand auf den Knopf zu legen
      // geht weiter, aber wer drei Schritte entfernt vor einer Tür steht,
      // drückt `A` und ist durch — statt davor zu hüpfen.
      if (!uiActive && !this.locked && input.get('right')?.primary.justPressed) {
        if (this.useCandidate) this.useWanted = true;
        else this.intentJump = true;
      }
    }

    // Was die Welt nach diesem Bild über den Wunsch wissen darf (Puste):
    // festgehalten, bevor der Wunsch für das nächste Bild gelöscht wird.
    this.wished = this.intent.lengthSq() > 0.0025;
    this.sprintedNow = this.sprintWanted || this.intentSprint;
    this.locomotion.apply(this, this.intent, this.intentJump, dt);
    this.intent.set(0, 0, 0);
    this.intentJump = false;
    this.intentSprint = false;

    if (presenting && !this.locked && this.menuStick !== 'right') {
      const turn = input.get('right')?.thumbstick.x ?? 0;
      if (this.turnMode === 'smooth') {
        const magnitude = Math.abs(turn);
        if (magnitude > 0.18) {
          const angle =
            -Math.sign(turn) * Math.min(1, (magnitude - 0.18) / 0.82) * this.smoothTurnSpeed * dt;
          this.rotateAroundHead(angle);
          turnWalkFrame(this.walkFrame, angle);
        }
        this.snapArmed = magnitude < 0.35;
      } else if (this.snapArmed && Math.abs(turn) > 0.7) {
        const angle = -Math.sign(turn) * this.snapAngle;
        this.rotateAroundHead(angle);
        // Der Snap dreht den ganzen Spieler; die gemerkte Laufrichtung dreht
        // mit, sonst liefe man nach der Drehung seitwärts weiter.
        turnWalkFrame(this.walkFrame, angle);
        this.snapArmed = false;
      } else if (Math.abs(turn) < 0.35) {
        this.snapArmed = true;
      }
    }
  }

  /** Walking speed right now — sprinting is a factor on top of it. */
  private speedNow(): number {
    if (this.pace) return this.pace(this.sprintWanted);
    // Nie unter Gehtempo: Wer den Sprintfaktor im Menü heruntergedreht hat,
    // soll durch eine leere Puste nicht **langsamer** werden als im Schritt.
    const sprint = Math.max(1, this.sprintFactor * Math.max(0, Math.min(1, this.sprintScale)));
    return this.moveSpeed * (this.sprintWanted ? sprint : 1);
  }

  /**
   * The sticks pressed in: left sprints, right crouches. Both can either be
   * held or toggled, which is what the settings switch between.
   *
   * Crouching lowers the rig, because in VR the headset — not us — decides
   * where the camera sits inside it. The body keeps its feet on the floor:
   * `getFloorY()` adds the drop back on, and the character controller shrinks
   * its capsule from the head height, which the drop has already shortened.
   */
  private updateStance(dt: number, input: XRInput): void {
    const left = input.get('left')?.stick;
    if (left) {
      if (this.sprintToggle) {
        if (left.justPressed) this.sprintWanted = !this.sprintWanted;
      } else {
        this.sprintWanted = left.pressed;
      }
    }

    const right = input.get('right')?.stick;
    if (right) {
      if (this.crouchToggle) {
        if (right.justPressed) this.crouchWanted = !this.crouchWanted;
      } else {
        this.crouchWanted = right.pressed;
      }
    }
    // Sprinting off somewhere stands the player up first — nobody sprints in
    // a crouch, and the two settings must not fight each other.
    const stick = input.get('left')?.thumbstick;
    const moving = stick ? stick.x !== 0 || stick.y !== 0 : false;
    if (this.crouchWanted && this.sprintWanted && moving) this.crouchWanted = false;

    this.updateSeatLift(dt);

    this.updateCrouch(dt);
  }

  private updateCrouch(dt: number): void {
    const target = this.crouchWanted ? this.crouchDepth : 0;
    if (target === this.crouchOffset) return;
    const step = THREE.MathUtils.clamp(
      target - this.crouchOffset,
      -this.crouchSpeed * dt,
      this.crouchSpeed * dt,
    );
    this.crouchOffset += step;
    this.position.y -= step;
    this.updateMatrixWorld(true);
  }

  /**
   * The lift a seated player gets: the gap between their own sitting and
   * standing eye height, added to the rig with the feet left behind.
   *
   * A fixed number rather than a live measurement, because leaning forward in
   * a chair is a perfectly normal thing to do and the world must not bob with
   * it — the ramp is the same slow one crouching uses, so a change to the
   * setting reads as the body settling rather than as the floor jumping.
   */
  private updateSeatLift(dt: number): void {
    const target = this.posture === 'sit' ? THREE.MathUtils.clamp(this.seatHeight, 0, 1.2) : 0;
    if (Math.abs(target - this.seatLift) < 1e-4) return;
    const step = THREE.MathUtils.clamp(
      target - this.seatLift,
      -this.crouchSpeed * dt,
      this.crouchSpeed * dt,
    );
    this.seatLift += step;
    this.position.y += step;
    this.updateMatrixWorld(true);
  }
}
